declare(strict_types=1);
const SV4_CONTRACT='2026-10-08-safety-vote-phase4-r1';
function sv4_num($v,float$d=0):float{return is_numeric($v)?(float)$v:$d;} function sv4_round($v):float{return round((float)$v,6);} function sv4_hash($v):string{return hash('sha256',json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));}
function sv4_config($r):array{$r=is_array($r)?$r:[];$m=in_array($r['method']??'', ['weighted_jury','hybrid','rank_points','allocation'],true)?$r['method']:'weighted_jury';$jw=max(0,sv4_num($r['juryWeight']??null,$m==='hybrid'?60:100));$pw=max(0,sv4_num($r['popularWeight']??null,$m==='hybrid'?40:0));$tie=in_array($r['tieBreak']??'', ['candidate_id','jury_score','popular_score'],true)?$r['tieBreak']:'candidate_id';return['method'=>$m,'juryWeight'=>$jw,'popularWeight'=>$pw,'topN'=>max(1,min(100,(int)sv4_num($r['topN']??null,1))),'threshold'=>sv4_num($r['threshold']??null,0),'minJurors'=>max(1,(int)sv4_num($r['minJurors']??null,1)),'minParticipation'=>max(0,(int)sv4_num($r['minParticipation']??null,0)),'tieBreak'=>$tie,'excludeHighLow'=>($r['excludeHighLow']??false)===true];}
function sv4_criteria($in):array{if(!is_array($in)||!$in||count($in)>50)return['ok'=>false,'errors'=>['CRITERIA_REQUIRED'],'criteria'=>[]];$seen=[];$errors=[];$out=[];foreach(array_values($in)as$i=>$x){$code=strtoupper(substr(trim((string)($x['criterionCode']??'C'.($i+1))),0,50));$min=sv4_num($x['minScore']??null,0);$max=sv4_num($x['maxScore']??null,10);$w=sv4_num($x['weight']??null,1);if(!$code||isset($seen[$code]))$errors[]='CRITERION_CODE_DUPLICATE';$seen[$code]=1;if(!trim((string)($x['title']??''))||$max<=$min||$w<=0)$errors[]='CRITERION_INVALID';$out[]=['id'=>isset($x['id'])?(int)$x['id']:null,'criterionCode'=>$code,'title'=>substr(trim((string)($x['title']??'')),0,300),'description'=>trim((string)($x['description']??''))?:null,'minScore'=>$min,'maxScore'=>$max,'weight'=>$w,'sortOrder'=>(int)($x['sortOrder']??$i+1)];}return['ok'=>!$errors,'errors'=>array_values(array_unique($errors)),'criteria'=>$out];}
function sv4_sheet(array$criteria,array$candidateIds,$scores):array{$by=[];foreach($criteria as$c)$by[(int)$c['id']]=$c;$allowed=array_fill_keys(array_map('intval',$candidateIds),true);$seen=[];$errors=[];$rows=[];foreach(is_array($scores)?$scores:[]as$x){$cid=(int)($x['candidateId']??0);$kid=(int)($x['criterionId']??0);$key="$cid:$kid";$c=$by[$kid]??null;$score=isset($x['score'])&&is_numeric($x['score'])?(float)$x['score']:NAN;if(!isset($allowed[$cid])||!$c||isset($seen[$key])||is_nan($score)||$score<(float)$c['minScore']||$score>(float)$c['maxScore']){$errors[]='SCORE_INVALID';continue;}$seen[$key]=1;$rows[]=['candidateId'=>$cid,'criterionId'=>$kid,'score'=>$score,'comment'=>substr(trim((string)($x['comment']??'')),0,1000)?:null];}foreach($allowed as$cid=>$_)foreach($criteria as$c)if(!isset($seen[$cid.':'.(int)$c['id']]))$errors[]='SCORE_MISSING';return['ok'=>!$errors,'errors'=>array_values(array_unique($errors)),'rows'=>$rows];}
function sv4_calculate(array$in):array{$cfg=sv4_config($in['config']??[]);$criteria=$in['criteria']??[];$candidateIds=array_values(array_unique(array_map('intval',$in['candidateIds']??[])));sort($candidateIds);$submitted=array_values(array_filter($in['sheets']??[],fn($s)=>($s['status']??'')==='Submitted'&&($s['conflictState']??'clear')!=='recused'));$popular=[];foreach($in['popular']??[]as$x)$popular[(int)$x['candidateId']]=sv4_num($x['value']??0);$participation=max(0,(int)sv4_num($in['participationCount']??0));$jur=[];foreach($submitted as$s)$jur[(string)$s['jurorEmployeeId']]=1;$quorum=$participation>=$cfg['minParticipation']&&count($jur)>=$cfg['minJurors']?'met':'not_met';$rows=[];foreach($candidateIds as$cid){$norm=[];foreach($submitted as$s){$sum=0;$weights=0;foreach($s['scores']??[]as$x)if((int)$x['candidateId']===$cid){$c=null;foreach($criteria as$z)if((int)$z['id']===(int)$x['criterionId']){$c=$z;break;}if($c){$sum+=((sv4_num($x['score'])-sv4_num($c['minScore']))/(sv4_num($c['maxScore'])-sv4_num($c['minScore'])))*sv4_num($c['weight']);$weights+=sv4_num($c['weight']);}}if($weights)$norm[]=$sum/$weights*100;}sort($norm);$vals=$norm;if($cfg['excludeHighLow']&&count($vals)>=3)$vals=array_slice($vals,1,-1);$jury=$vals?array_sum($vals)/count($vals):0;$pop=$popular[$cid]??0;$total=$cfg['method']==='hybrid'?($jury*$cfg['juryWeight']+$pop*$cfg['popularWeight'])/($cfg['juryWeight']+$cfg['popularWeight']?:1):(in_array($cfg['method'],['allocation','rank_points'],true)?$pop:$jury);$rows[]=['candidateId'=>$cid,'juryScore'=>sv4_round($jury),'popularScore'=>sv4_round($pop),'totalScore'=>sv4_round($total),'judgeCount'=>count($norm)];}usort($rows,function($a,$b)use($cfg){if($a['totalScore']!==$b['totalScore'])return$b['totalScore']<=>$a['totalScore'];if($cfg['tieBreak']==='jury_score'&&$a['juryScore']!==$b['juryScore'])return$b['juryScore']<=>$a['juryScore'];if($cfg['tieBreak']==='popular_score'&&$a['popularScore']!==$b['popularScore'])return$b['popularScore']<=>$a['popularScore'];return$a['candidateId']<=>$b['candidateId'];});$tie='none';foreach($rows as$i=>&$r){$r['rank']=$i+1;$r['advanced']=$quorum==='met'&&$r['rank']<=$cfg['topN']&&$r['totalScore']>=$cfg['threshold'];if($i&&$r['totalScore']===$rows[$i-1]['totalScore'])$tie='resolved';}unset($r);$payload=['contract'=>SV4_CONTRACT,'config'=>$cfg,'quorumState'=>$quorum,'tieState'=>$tie,'participationCount'=>$participation,'submittedJurors'=>count($jur),'rows'=>$rows];return$payload+['inputHash'=>sv4_hash(['config'=>$cfg,'criteria'=>$criteria,'candidateIds'=>$candidateIds,'sheets'=>$submitted,'popular'=>$popular]),'resultHash'=>sv4_hash($payload)];}
function sv4_stages($in):array{if(!is_array($in)||!$in)return['ok'=>false,'errors'=>['STAGES_REQUIRED'],'stages'=>[]];$errors=[];$keys=[];$seq=[];$out=[];foreach(array_values($in)as$i=>$x){$key=strtoupper(substr(trim((string)($x['stageKey']??'STAGE_'.($i+1))),0,50));$n=(int)sv4_num($x['sequenceNo']??null,$i+1);if(isset($keys[$key])||isset($seq[$n])||!trim((string)($x['stageName']??'')))$errors[]='STAGE_INVALID';$keys[$key]=1;$seq[$n]=1;$out[]=['id'=>isset($x['id'])?(int)$x['id']:null,'stageKey'=>$key,'stageName'=>substr(trim((string)($x['stageName']??'')),0,160),'stageType'=>substr((string)($x['stageType']??'jury'),0,40),'sequenceNo'=>$n,'advanceRule'=>['topN'=>max(1,(int)sv4_num($x['advanceRule']['topN']??null,1)),'threshold'=>sv4_num($x['advanceRule']['threshold']??null,0),'blind'=>($x['advanceRule']['blind']??false)===true],'resultVisibility'=>(string)($x['resultVisibility']??'admin_only'),'status'=>(string)($x['status']??'Draft')];}usort($out,fn($a,$b)=>$a['sequenceNo']<=>$b['sequenceNo']);return['ok'=>!$errors,'errors'=>array_values(array_unique($errors)),'stages'=>$out];}
